131	      return settle({ ok: true });
132	    }
133	    case "undo": {
134	      if (!at.offer.undo) return settle({ ok: false, say: "There is nothing to take back." });
135	      act.undo();
136	      return settle({ ok: true });
137	    }
138	    case "answer": {
139	      if (!press.answer) return settle({ ok: false, say: "That answer was empty." });
140	      act.answer(press.answer);
141	      return settle({ ok: true });
142	    }
143	    default:
144	      return settle({ ok: false, say: "This run does not know that press." });
145	  }
146	}
