```tsx
/**
 * A press from a deck, taken here because this is the device holding the
 * run. What the deck may press is the offer this device published; what
 * happens when it does is the same function the page's own button calls.
 */
const seen = useRef(new Map<string, Verdict>());
useEffect(() => {
  if (!publishing || !run.record || !run.state) return;
  return syncBus.subscribe((news) => {
    if (news.t !== "drive" || news.id !== run.record?.runId) return;
    const verdict = takePress(news, { seq: run.events.length, offer: currentOffer, seen: seen.current }, {
      primary: () => run.begin(),
      move: (id) => run.takeMove(id),
      undo: () => run.undo(),
      answer: (a) => run.declareSubject(String(a["subject"] ?? "")),
    });
    live?.drove(news.from, news.ref, verdict.ok, verdict.say);
  });
}, [publishing, run, currentOffer, live]);
```

Hoist the `offerOf(...)` call from Task 6 into a `useMemo` named `currentOffer` so the publisher and this both read one value rather than computing it twice.

